def extract_point_from_text(text, point):
    pattern = rf"{point}[\s\S]*?(\d+)"
    match = re.search(pattern, text)

    if match:
        return int(match.group(1))

    return None

def extract_number(text):
    # 1. убрать zero-width и переносы строк
    text = re.sub(r'[\u200b\n]', '', text)

    # 2. найти число (включая однозначные)
    match = re.search(r'(\d+(?:[\s,.]\d+)*)', text)
    if not match:
        return None

    value = match.group()
    value = re.sub(r'\s+', '', value)
    value = value.replace(',', '.')
    value = re.sub(r'[^0-9.]', '', value)

    # если несколько точек — оставить первую
    if value.count('.') > 1:
        first = value.find('.')
        value = value[:first+1] + value[first+1:].replace('.', '')

    # -------- X2 ПРОВЕРКА (игнорируя точку) --------
    raw_digits = value.replace('.', '')

    if len(raw_digits) >= 4 and len(raw_digits) % 2 == 0:
        pairs_ok = True
        for i in range(0, len(raw_digits), 2):
            if raw_digits[i] != raw_digits[i+1]:
                pairs_ok = False
                break

        if pairs_ok:
            fixed = raw_digits[::2]

            if '.' in value:
                decimals = len(value.split('.')[-1]) // 2
                fixed = fixed[:-decimals] + '.' + fixed[-decimals:]

            value = fixed

    try:
        return float(value)
    except:
        return None

def extract_points_from_pdf_url(url, target_points, default_type="number", point_types=None):

    if point_types is None:
        point_types = {}

    results = {point: [] for point in target_points}

    response = requests.get(url)
    response.raise_for_status()

    with pdfplumber.open(BytesIO(response.content)) as pdf:
        for page in pdf.pages:
            tables = page.extract_tables()

            for table in tables:
                for row in table:
                    if not row:
                        continue

                    row = [cell if cell else "" for cell in row]

                    for point in target_points:
                        if any(cell.strip() == point for cell in row):

                            cell_value = row[-1].strip()

                            value_type = point_types.get(point, default_type)

                            if value_type == "number":
                                value = extract_number(cell_value)
                                if value is not None:
                                    results[point].append(value)

                            elif value_type == "str":
                                if cell_value:
                                    results[point].append(cell_value)

                            else:
                                raise ValueError("type must be 'number' or 'str'")


            text = page.extract_text()

            if text:
                for point in target_points:
                    if not results[point]:
                        pattern = rf"{point}[\s\S]*?(\d+)"
                        match = re.search(pattern, text)

                        if match:
                            results[point].append(int(match.group(1)))
                            print(f"TEXT fallback used for {point}")

    final_results = {}

    for k, v in results.items():
        value_type = point_types.get(k, default_type)

        if value_type == "number":
            final_results[k] = sum(v) if v else None
        else:
            final_results[k] = v if v else None

    return final_results

